import { requestHub, type ConnectedHub } from './HubClient';
import { withLaunchRuntime } from '../utils/launchRuntime';

export const libraryPageUrl = ({
  hub,
  path,
}: {
  hub: ConnectedHub;
  path: string;
}): URL => {
  const url = new URL(path, hub.url);
  url.hostname = 'localhost';
  return url;
};

export const createLibraryLaunchUrl = async ({
  hub,
  path,
  callerAgent,
}: {
  hub: ConnectedHub;
  path: string;
  callerAgent?: string;
}): Promise<string> => {
  const { code } = await requestHub<{ code: string }>({
    hub,
    endpoint: '/launch-codes',
    body: {},
  });
  const url = libraryPageUrl({ hub, path });
  url.hash = new URLSearchParams({ code }).toString();
  return withLaunchRuntime(url.toString(), callerAgent);
};
